import pathlib,json,subprocess,os
r={'uname':subprocess.run(['uname','-r'],capture_output=True,text=True).stdout.strip(),'usr_src':[str(p) for p in pathlib.Path('/usr/src').iterdir()]}
paths=[pathlib.Path('/lib/modules')/r['uname']/'build']
r['build']=[str(p.resolve()) for p in paths]
hits={}
for base in paths:
 for suffix in ['include/linux/netdevice.h','include/net/netdev_queues.h','include/net/netdev_lock.h','include/net/netdev_rx_queue.h','include/linux/netdevice-napi.h','net/core/dev.c','net/core/net-sysfs.c']:
  p=base/suffix
  if not p.is_file():continue
  lines=p.read_text().splitlines();selected=[]
  needles=['gro_flush_timeout','napi_get_defer_hard_irqs','netdev_set_defer_hard_irqs','napi_defer_hard_irqs']
  for i,line in enumerate(lines):
   if any(n in line for n in needles):
    selected.append({'line':i+1,'context':'\n'.join(lines[max(0,i-5):min(len(lines),i+12)])})
  if selected:hits[str(p)] = selected
r['hits']=hits
print(json.dumps(r,indent=2))
